// keyring — multi-key store with rotation
// KDF: 100000, key size: sha256

fn new_keyring::() {
    return {"keys": {}, "primary": null, "version": 1};
}

fn add_key::(kr, label, material) {
    let key = @crypto_pbkdf2(material, label, 32, sha256);
    kr["keys"][label] = @base64(key);
    if (kr["primary"] == null) { kr["primary"] = label; }
    return label;
}

fn remove_key::(kr, label) {
    if (@map_has_key(kr["keys"], label)) {
        kr["keys"] = @map_omit_keys(kr["keys"], [label]);
        if (kr["primary"] == label) {
            let remaining = @map_keys_sorted(kr["keys"]);
            kr["primary"] = @len(remaining) > 0 ? remaining[0] : null;
        }
        return true;
    }
    return false;
}

fn set_primary::(kr, label) {
    if (!@map_has_key(kr["keys"], label)) { @raise("keyring: unknown label"); }
    kr["primary"] = label;
    return label;
}

fn primary_key::(kr) {
    if (kr["primary"] == null) { @raise("keyring: no primary key"); }
    return @base64_decode(kr["keys"][kr["primary"]]);
}

fn key_by_label::(kr, label) {
    if (!@map_has_key(kr["keys"], label)) { @raise("keyring: unknown label"); }
    return @base64_decode(kr["keys"][label]);
}

fn encrypt_with::(kr, label, plaintext) {
    let key = key_by_label(kr, label);
    let mem = @mem_from_bytes(@bytes(plaintext));
    @mem_encrypt(mem, key);
    let out = @base64(@mem_to_bytes(mem));
    @free(mem);
    return out;
}

fn decrypt_with::(kr, label, ciphertext) {
    let key = key_by_label(kr, label);
    let mem = @mem_from_bytes(@base64_decode(ciphertext));
    @mem_decrypt(mem, key);
    let out = @mem_to_string(mem);
    @free(mem);
    return out;
}

fn rotate_primary::(kr, new_material) {
    let new_label = "primary_" + @str(@len(@map_keys_sorted(kr["keys"])));
    add_key(kr, new_label, new_material);
    set_primary(kr, new_label);
    return new_label;
}

fn labels::(kr) { return @map_keys_sorted(kr["keys"]); }

fn version::() { return "1.0.0"; }
